#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string inp;
    std::getline(std::cin, inp);
    int state = 0;
    std::string text = inp;
    // Replace "at" with "@" and "dot" with "."
    size_t pos;
    while ((pos = text.find("at")) != std::string::npos) {
        text.replace(pos, 2, "@");
    }
    while ((pos = text.find("dot")) != std::string::npos) {
        text.replace(pos, 3, ".");
    }
    std::vector<char> chars_list(text.begin(), text.end());
    int length = chars_list.size();

    if (length > 0) {
        if (chars_list[0] == '.') {
            chars_list[0] = 'd'; // placeholder for "dot"
        }
        if (chars_list[length - 1] == '.') {
            chars_list[length - 1] = 'd'; // placeholder for "dot"
        }
        if (chars_list[0] == '@') {
            chars_list[0] = 'a'; // placeholder for "at"
        }
        if (chars_list[length - 1] == '@') {
            chars_list[length - 1] = 'a'; // placeholder for "at"
        }
    }

    for (int i = 0; i < length; ++i) {
        if (chars_list[i] == '@' && state == 0) {
            state = 1;
        } else if (chars_list[i] == '@') {
            chars_list[i] = 'a'; // placeholder for "at"
        }
        std::cout << chars_list[i];
    }
    return 0;
}
